;-----------------------------------------------;;   Imported address;;-----------------------------------------------	IMPORT QDStart2*****************************************************************			   **              Patches to Routines that	do RgnDefs	   **	  for ROM Version 2.0	   **			   ** System Disk 2.0			   **			   ** May 9, 1987   Steven E. Glass		   **			   ** System Disk 2.1			   **			   ** June 1987   Steven Glass		   **			   **    PutRgn expect the rgn to be put in	RgnHandleA.  StdRgn	   **    expected it in	RgnHandleC.  The patch copies RgnHandleC   **    to RgnHandleA and then jumps back into ROM.	   **			   ** System Disk 2.1  July 7, 1987  Steven	Glass & Art Cabral	   **			   **    InsetRgn did not work for negative	values on some	   **    regions.  Problem was in InsetScan	but to patch	   **    we have to patch out RgnOp.		   **			   ** 6/7/89	Mensch** Patched rgnOp so that it functions in low memory situations* when there is not 10k available maxblock.*** 4/4/90	Mensch*	Must rewrite entire DoRgnOp routine*	because it has MANY insestuous quickdraw calls that can cause*	handles to stay locked in many instances. I will take the original*	code and try to work some sort of magic on it to insure that the*	two regions passed it are always unlocked.**********************************************************************************************************************************			   **              Copyright (C) 1985-1987		   **              All Rights Reserved		   **              Apple Computer, Inc.		   **			   *****************************************************************	include 'all.macros'	include 'special.macros'		include ':::qd:qdequates:qd.data.asm'	INCLUDE ':::qd:QDEquates:core.globals1'	INCLUDE ':::qd:QDEquates:core.globals2'	INCLUDE ':::qd:QDEquates:region.equs'	INCLUDE ':::qd:QDEquates:rect.equs'	INCLUDE ':::qd:QDEquates:slab.equs'	INCLUDE ':::qd:QDEquates:rgndefs.equs'		import LocalQDStart	Entry DoRgnOp*******************************************************************************;; Following is all ROM addresses needed by this file...RgnBEmpty	equ $FE5EB2RgnAEmpty	equ $FE5E9BRgnSector	equ $FE5EC9TheRTL	equ $FE5E7A	; address of an RTL in ROM 1BusyErr12	equ $FEFF58BusyEC12	equ $FEFF55ROMNotEasy	equ $FE601A	MACRO&lab	ROMCALL &where&lab	phk	pea @1-1	pea |TheRTL-1	jml &where@1	MEND****************************************************************** Procedure SectRgn(*   srcRgnA,srcRgnB,dstRgn:RgnHandle*   )**   Calculate the intersection of two regions.*****************************************************************SectRgn	PROC Export	jsr LocalQDStart	lda #0	; op := Sect	jmp DoRgnOp	; it does all the work	ENDP****************************************************************** Procedure UnionRgn(*   srcRgnA,srcRgnB,dstRgn:RgnHandle*   )**   Calculate the union of two regions.*****************************************************************UnionRgn	PROC Export	jsr LocalQDStart	lda #4	; op := Union	jmp DoRgnOp	; it does all the work	ENDP****************************************************************** Procedure DiffRgn(*   srcRgnA,srcRgnB,dstRgn:RgnHandle*   )**   Calculate the difference A-B of two	regions.*****************************************************************DiffRgn	PROC Export	jsr LocalQDStart	lda #2	; op := Diff	jmp DoRgnOp	; it does all the work	ENDP****************************************************************** Procedure XorRgn(*   srcRgnA,srcRgnB,dstRgn:RgnHandle*   )**   Calculate the exclusive or of two regions.*****************************************************************XorRgn	PROC Export	jsr LocalQDStart	lda #6	; op := Xor	jmp DoRgnOp	; it does all the work	ENDP****************************************************************** Procedure DoRgnOp;**   Computes the Intersection, Difference, Union, or Xor*   of two regions.	 Enter with Op in A.**    Sect = 0	A-B Diff = 2      Union = 4      Xor = 6*****************************************************************	EXPORT DoRgnOpDoRgnOp	PROC*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3DstRgn	equ RTL2+3SrcRgnB	equ DstRgn+4SrcRgnA	equ SrcRgnB+4	sta Op	; save the operation		lda SrcRgnA,s	; get low word of SrcRgnA	sta RgnHandleA	; save it	lda SrcRgnA+2,s	; get high word of SrcRgnA	sta RgnHandleA+2	; save it	lda SrcRgnB,s	; get low word of SrcRgnB	sta RgnHandleB	; save it	lda SrcRgnB+2,s	; get high word of SrcRgnB	sta RgnHandleB+2	; save it	jsr DerefAB	lda [RgnPtrA]	; get size of one	cmp [RgnPtrB]	; compare to size of other	bne NotSame	; if not the same drop to the new rgnop...	tay	dey	deyLoop	lda [RgnPtrA],y	cmp [RgnPtrB],y	bne NotSame	dey	dey	bne Loop; was this...;	pha	; room for result;	lda SrcRgnA+4,s	; get high word;	pha	; push it;	lda SrcRgnA+4,s	; get low word;	pha	; push it;	lda SrcRgnA+4,s	; get high word;	pha	; push it;	lda SrcRgnA+4,s	; get low word;	pha	; push it;	_EqualRgn	; are they equal?;	pla	; get boolean result;	beq NotSame	; if 0 (false), we have more work; NOTE: If we get here then the regions are the same...	lda Op	; get op	and #2	; and it with 2 (Diff and Xor bit)	bne Zero	; zero it if Sect or UnionCopy	; This routine copies rgn <A> to dest region...	lda SrcRgnA+2,s	; get high word	pha	; push it	lda SrcRgnA+2,s	; get low word	pha	; push it	lda DstRgn+6,s	; get high word	pha	; push it	lda DstRgn+6,s	; get low word	pha	; push it	_CopyRgn	; copy it	bcs T1	brl DoUnlockABNoErrZero	lda DstRgn+2,s	; get high word	pha	; push it	lda DstRgn+2,s	; get low word	pha	; push it	_SetEmptyRgn	; zero the destination	bcs T1	brl DoUnlockABNoErrT1	brl DoUnlockABError* load the handles from the stack onto zero page and dereference themNotSame	; was this...;	lda SrcRgnA,s	; get low word of SrcRgnA;	sta RgnHandleA	; save it;	lda SrcRgnA+2,s	; get high word of SrcRgnA;	sta RgnHandleA+2	; save it;	jsr DerefA;;	lda SrcRgnB,s	; get low word of SrcRgnB;	sta RgnHandleB	; save it;	lda SrcRgnB+2,s	; get high word of SrcRgnB;	sta RgnHandleB+2	; save it;	jsr DerefB* If Op = Diff and RgnB is empty, copy RgnA into DstRgn	lda #2	; get Diff opcode	cmp Op	; is it Diff?	bcc UniXor	; if Op > Diff then	Union or Xor	bne BBoxes	; if Op <> Diff, it's Sect* Op = Diff, so check RgnB for empty	ROMCALL RgnBEmpty	; is RgnB empty	bpl Copy	; if it's empty, CopyRgnA* If Op = Sect or Diff, then intersect the bounding boxes.BBoxes	ROMCALL RgnSector	; RgnY1..RgnX2 := RgnA * RgnB	lda RgnX1	cmp RgnX2	; compare to X2	bpl Empty	; if X1=X2, it's empty	lda RgnY1	; get top	cmp RgnY2	; if Y1 >= Y2, it's empty	bmi NotEmpty	; so do it* The bounding boxes don't intersect.  If Op = Sect, then return empty.* If Op = Diff, then copy RgnA into DstRgnEmpty	lda Op	; get op	beq Zero	; if Sect, return empty	jmp Copy	; no, copy SrcA into DstRgn* If Op = Sect, then check for both inputs rectangularNotEmpty	lda Op	; is op = Sect	bne NotEasy	; no, continue	lda #10	; get rectangular region size	cmp [RgnPtrA]	; compare with RgnA	length	bne NotEasy	; no, continue	cmp [RgnPtrB]	; compare with RgnB	length	bne NotEasy	; no, continue* push dstrgn and address of temprect.	Could be bad news.	lda DstRgn+2,s	; get high word	pha	; push it	lda DstRgn+2,s	; get low word	pha	; push it	clc	lda #0	; it's in bank 0	pha	; push high word	tdc	; get direct register	adc #RgnY1	; add in offset	pha	; push low word	_RectRgn	; RectRgn(dstRgn,tempRect)	bcs T2	brl DoUnlockABNoErrT2	brl DoUnlockABErrorUniXor	ROMCALL RgnBEmpty	; is RgnB empty?	bmi T3	; yes, copy RgnA	brl CopyT3	ROMCALL RgnAEmpty	; is RgnA empty?	bmi NotEasy	; yes, copy RgnB	lda SrcRgnB+2,s	; get high word	pha	; push it	lda SrcRgnB+2,s	; get low word	pha	; push it	lda DstRgn+6,s	; get high word	pha	; push it	lda DstRgn+6,s	; get low word	pha	; push it	_CopyRgn	; copy it	bcs DoUnlockABErrorDoUnlockABNoErr	phx	jsr UnlockAB	plx	JML BusyEC12DoUnlockABError	pha	jsr UnlockAB	plx	JML BusyErr12NotEasy	clc	; clear carry for addition	lda [RgnPtrA]	; get RgnA length	adc [RgnPtrB]	; add RgnB length	asl A	; double (Quickdraw	did ADD D4,D4)	sta PtCount	; save it* We've taken all the shortcuts we can.  Now we pass the buck to RgnOp to do* the real work.  The source regions are still in RgnHandleA and RgnHandleB.* PtCount contains the maximum size we should need.  Load X	with 0 since we* have no horizontal offset to worry about (just for cleanliness).	ldx #0	; unnecessary unless code changes	jsl RgnOp	; do it	bcs RgnOpError	; RgnOp propogates errors	lda DstRgn,s	sta RgnHandleA	lda DstRgn+2,s	sta RgnHandleA+2	jsr DerefA	; nice shortcut...	jsl PackRgn	; call it	PushLong BufHandle	; push handle	_DisposeHandle	; dispose of point buffer handle	bcs DoUnlockABError	brl DoUnlockABNoErrRgnOpError	pha	; save error code	lda BufHandle	ora BufHandle+2	beq DontDispose	PushLong BufHandle	_DisposeHandleDontDispose	jsr UnlockAB	plx	; get error code back	jmp BusyErr12UnlockAB	; modified this routine to unblock the src rgns on the stack instead; first save the direct page...	phd	plx	; in the <X> register...	tsc	; and make the stack a direct page	tcd	ldy #4	; offset to the handle attributes	lda [SrcRgnA+4],y	; unlock A (account for error and jsr)	and #$7FFF	sta [SrcRgnA+4],y	lda [SrcRgnB+4],y	; unlock B	and #$7FFF	sta [SrcRgnB+4],y	phx	; restore direct page	pld	; to what it was before...	rtsDeRefAB		ldy #4	; lock it	lda [RgnHandleB],y	ora #$8000	sta [RgnHandleB],yDerefA	ldy #4	; lock it	lda [RgnHandleA],y	ora #$8000	sta [RgnHandleA],y	lda [RgnHandleA]	; deref it.	sta RgnPtrA	lda [RgnHandleB]	; deref it.	sta RgnPtrB	ldy #2	lda [RgnHandleA],y	sta RgnPtrA+2	lda [RgnHandleB],y	sta RgnPtrB+2	rts	ENDP****************************************************************** Function RectInRgn2** Change History** 06 May 87       Steven Glass**    This code was not handling the Rectangular region*    correctly.  It	was trying to dispose a handle that*    was not there and returned a random error code.**    The reason it tried to dispose of the handle that was*    not there was it looked at the wrong variable to see*    if had been allocated.**    This patch zeros the wrong variable and jumps into the*    original code.*****************************************************************	EXPORT RectInRgn2RectInRgn2	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3Rgn	equ RTL2+3RectPtr	equ Rgn+4Result	equ RectPtr+4RgnFlag	equ PtCount+2	jsr QDStart2	stz BufPtr	stz BufPtr+2	jml $FE52cB	ENDP;                copy rdf.patch2/putrgn******************************************************************* Procedure PutRgn** Change History   9 Jun 87** Input to PutRgn is RgnHandleA.  Unfortunately, input to* StdRgn is RgnHandleC.** This patch copies	RgnHandleC to RgnHandleA and jumps into	the* old code.*****************************************************************	EXPORT iPutRgn2iPutRgn2	PROCOldPutRgn	equ $FE5604	lda RgnHandleC	sta RgnHandleA	lda RgnHandleC+2	sta RgnHandleA+2	jml OldPutRgn	ENDP;                copy rdf.patch2/rgnop	EXPORT iRgnOp2iRgnOp2	PROCRgnOpInROM	equ $FE5CD4RgnOpInROMAlt	equ $FE5D3FMyRgnAttributes	equ 0	lda Op	cmp #8	bne @1	brl UsePatch@1	jsr MakeScratchHand	; make the scratch buffer the proper size...	jml RgnOpInROMAlt	; jump in after the patch	;MyFlag	ds.W 1	; used by MakeScratch;;---------------------------------------------------------------; MakeScratchHand; This routine will create a scratch handle for qd region ops; this handle will be alocated with 10k first, but if 10k is too large; it will try smaller handles till it gets one it can use,; if it can not alocate a handle of any size, it exits with an errorMakeScratchHandFakeA	equ 0	; offset to FakeA regionFakeB	equ FakeA+18	; offset to FakeB regionScan	equ FakeB+18	; offset to start of scan buffersScratchSize	equ 10280	; 10 K of space, maximumPartition	equ 2048	; size of one partitionSmallPartition	equ 768	; Size of low mem partitions!ScratchMaxSize	equ 10280ScratchMinSize	equ 10280-5120	; shrink it by 5 k	stx DH	; save horizontal offset	stz BufHandle	; zero handle to nil	stz BufHandle+2	stz outscan	; zero our flag		lda >MyFlag	; test to see if we can try for more memory	beq @tryBig	and #$001F	; lower the flag by 1	dec a	sta >MyFlag	nop	; for handy hand patching...	nop	nop	nop	lda #ScratchMinSize	sta outscan	bra @cont1@tryBig	lda #ScratchMaxSize@cont1	pha	; save the size on the stack	@Loop	ldx #ScratchHandle	; offset	lda 1,s	; length of new handle	jsr LocalGetNewHandle ; new, deref, lock, set size	bcc @gotIt; if we get here the handle is not alocated yet...	pla	; get the old size	cmp #ScratchMaxSize	; first time?	bne @NoRoomAtTheInn	; If not, just explode	lda #10	; next 10 rgnops no allocate	sta >MyFlag	lda #ScratchMinSize	; shrink us by 5k	sta outscan	pha	nop	nop	nop	nop	bra @Loop@NoRoomAtTheInn	sec	; just exit here I guess	lda #$0201	rtl@GotIt	ply	; discard the size of the handle	ldy #2	; boy is this routine neutral...;; Now do the rest of the setup stuff	sta Scratch	; save pointer	stx Scratch+2	lda PtCount	; get size of BufHandle	ldx #BufHandle	; get offset	jsr LocalGetNewHandle	bcc T2	; if an error, return it	brl MemErrorT2	sta BufPtr	stx BufPtr+2	ldy #2	lda #4	sta [BufPtr],y	; initialize buffer	index* Move RgnPtrA to FakeA and expand it to a 4 point packed region if rectangular	jsr ExpandA	; expand FakeA	jsr ExpandB	; expand FakeB* Initialize assorted pointers	sec	; prepare for subtract	lda PtCount	; get size of BufHandle	sbc #4	; remove length and	index bytes	and #$FFF8	; truncate to an integral # of points	clc	; prepare for add	adc #4	; put length and index bytes back in	sta ListMax	; biggest we can handle	ldy #4	; offset to first buffer dest	sty ListPtr	; save it	ldy #Scan	; offset to first scan buffer	lda #MaxInt	; get MaxInt	sta [Scratch],y	; initialize ScanA to empty	sty ScanA	; save it in ScanA	ldy outscan	; test our flag	beq @theOldWay	; do it the old way	ldy #(Scan+SmallPartition) ; offset to second scan buffer	sta [Scratch],y	; initialize ScanB to empty	sty ScanB	; save it in ScanB	ldy #(Scan+SmallPartition*2) ; offset to third scan buffer	sta [Scratch],y	; initialize ScanC to empty	sty ScanC	; save it in ScanC	ldy #(Scan+SmallPartition*3) ; offset to fourth scan buffer	sty TempScan	; save it in TempScan	ldy #(Scan+SmallPartition*4) ; offset to fifth scan buffer	sty OutScan	; save it in OutScan	rts@theOldWay	ldy #(Scan+Partition) ; offset to second scan buffer	sta [Scratch],y	; initialize ScanB to empty	sty ScanB	; save it in ScanB	ldy #(Scan+Partition*2) ; offset to third scan buffer	sta [Scratch],y	; initialize ScanC to empty	sty ScanC	; save it in ScanC	ldy #(Scan+Partition*3) ; offset to fourth scan buffer	sty TempScan	; save it in TempScan	ldy #(Scan+Partition*4) ; offset to fifth scan buffer	sty OutScan	; save it in OutScan	rtsUsePatch		;****************************************************************** Procedure RgnOp;**   Accepts two source regions in RgnHandleA and RgnHandleB	and*   assumes they have been dereferenced	and locked down.  It*   creates a buffer based on PtCount.	The horizontal offset*   used in the event of and InsetRgn call is passed in register*   X.  The operation to perform is passed in Op.**   Computes the intersection, difference, union, or xor of*   two regions or the horizontal inset	of one region, and stores*   the result as an unpacked array of sorted inversion points*   in bufHandle.  Returns the number of points in PtCount.*   BufHandle will be grown only if more space is needed.  RgnOp*   returns an error if one is returned	from the memory manager.**    Sect = 0   A-B	Diff = 2   Union = 4   Xor = 6   HInset	= 8** Change History** 7 July 87    SEG	   (System Disk 2.1)** This proc is patched to be able to get to InsetScan* below.  This code	is only run when the operation to perform* is inset.  Other operations go through ROM.** The code here is almost identical to the code in ROM.  We	have* removed references to code that will not be run.** We also found a bug in a error handling path.  If a memory* error occured, the MemError routine below did a JSR to* GetRidOfS.  GetRidOfS ends in an RTL.	 This bug still* exists in ROM and	can be encountered when doing operations* other than Inset.****************************************************************** We generate some scratch space - an awful process but we have to get* the memory we need from somewhere - might as well grab it	all at once.* Here follows the usage of that memory.;	stx DH	; save horizontal offset;	stz BufHandle	; zero handle to nil;	stz BufHandle+2;;;	ldx #ScratchHandle	; offset;	lda #Scratchsize	; length of new handle;	jsr LocalGetNewHandle ; new, deref, lock, set size;	bcc T1;	rtl	; leave, propogating error		jsr MakeScratchHand	; call the local make scratch handle and other startup stuff	Movelong Scratch,SrcBase1 ; initialize SrcBase1	ldy PtrA	; get PtrA	lda [PtrBaseA],y	; NextA := first vert in A	sta NextA	; save it	IncYWd	; bump y to next word	sty PtrA	; save it	ldy PtrB	; get PtrB	lda [PtrBaseB],y	; NextB := first vert in B	sta NextB	; save it	IncYWd	; bump y to next word	sty PtrB	; save it	lda Op	; get Op	cmp #8	; is it Inset	bne NxtVert	; no, continue	lda #MaxInt	; get maxint	sta NextB	; save it in NextBNxtVert	lda NextA	; get NextA	cmp NextB	; set flags on NextA - NextB	beq Both	; they're equal, bump both	bpl UpdateB	; B, update RgnB only	jsr UpdateA	; A, update RgnA only	bra CalcUpdateA	lda NextA	; get NextA	sta Vert	; Vert := NextA	Movelong PtrBaseA,SrcBase1 ; establish the source base pointer	ldy PtrA	; get PtrA	sty Src1	; Src1 := PtrA	ldy ScanA	; get ScanA	sty Src2	; Src2 := ScanA	ldy TempScan	; get TempScan	sty Dst	; Dst := TempScan	jsr XorScan	; XorScan(PtrA,ScanA,TempScan)	Movelong Scratch,SrcBase1 ; put it back	where it belongs	ldy Src1	; get Src1; y is PtrA, bu	lda [PtrBaseA],y	; get next vert	sta NextA	; NextA := next Vert	IncYWd	; bump y	sty PtrA	; save it	ldx TempScan	; get TempScan	lda ScanA	; get ScanA	stx ScanA	; swap them	sta TempScan	; like so	rts	; return to local caller* When we get to Both, the A register contains the next vertical.  If it* is Maxint, we're done.XDone	jmp Done	; relay branchBoth	cmp #MaxInt	; is it Maxint?	beq XDone	; if so, all done	jsr UpdateA	; update RgnAUpdateB	lda NextB	; vert := NextB	sta Vert	; do it	Movelong PtrBaseB,SrcBase1 ; establish the source base pointer	lda PtrB	; get PtrB	sta Src1	; Src1 := PtrB	lda ScanB	; get ScanB	sta Src2	; Src2 := ScanB	lda TempScan	; get TempScan	sta Dst	; Dst := TempScan	jsr XorScan	; XorScan(PtrB,ScanB,TempScan)	Movelong Scratch,SrcBase1 ; put it back	where it belongs	ldy Src1	; get Src1	lda [PtrBaseB],y	; get next vert	sta NextB	; NextB := next vert	IncYWd	; bump y	sty PtrB	; PtrB := end of scan + 2	ldx TempScan	; get temp scan	lda ScanB	; get ScanB	stx ScanB	; swap them	sta TempScan	; like so* Calculate sect, diff, union, xor, or inset into ScanCCalc	lda ScanA	; get ScanA	sta Src1	; Src1 := ScanA	lda ScanB	; get ScanB	sta Src2	; Src2 := ScanB	lda TempScan	; get TempScan	sta Dst	; Dst := TempScan	ldx Op	; fetch Op (0,2,4,6,8)	jsr (CaseTab,x)	; execute OpScan	bra Changes	; jump around casetabCaseTab	dc.w 0	; SectScan'          ; address of SectScan	dc.w 0	; DiffScan'          ; address of DiffScan	dc.w 0	; UnionScan'         ; address of UnionScan	dc.w 0	; XorScan'           ; address of XorScan	dc.w InsetScan	; address of InsetScanChanges	lda TempScan	; get TempScan	sta Src1	; Src1 := TempScan	lda ScanC	; get ScanC	sta Src2	; Src2 := ScanC	ldy OutScan	; get offset to OutScan	sty Dst	; Dst := OutScan	jsr XorScan	; XorScan(TempScan,ScanC,OutScan)	ldx TempScan	; get TempScan	lda ScanC	; get ScanC	stx ScanC	; swap them	sta TempScan	; like so	ldy OutScan	; where the data was placed	sty Src1	; index we'll use to fetch it	ldy ListPtr	; so the comparison	will work	bra OutTest	; go to loop startOutLoop	lda [Scratch],y	; get H coord from OutScan	sta Temp	; save it	IncYWd	; bump y to next H offset	lda [Scratch],y	; get next H coord from OutScan	sta Temp+2	; save it too	IncYWd	; bump y again	sty Src1	; tuck it away	ldy ListPtr	; get output destination offset	lda Vert	; get V back	sta [BufPtr],y	; save it	IncYWd	; bump y	lda Temp	; get H	sta [BufPtr],y	; save it	IncYWd	; bump y	lda Vert	; get V value	sta [BufPtr],y	; save it	IncYWd	; bump y	lda Temp+2	; get H	sta [BufPtr],y	; save it	IncYWd	; bump y	sty ListPtr	; save itOutTest	cpy ListMax	; set flags on ListPtr-ListMax	bcc SizeOk	; if ListMax > ListPtr, continue* The point buffer is full.  Grow it if	Flags <> 0.	lda ListMax	; get current useful size	clc	; clear carry	adc #256	; bump by 256 bytes	sta ListMax	; the new value, already trimmed	ldx #BufHandle	; get offset	jsr LocalResizeHandle ; resize it, relock it	bcs MemError	sta BufPtr	; save new pointer	stx BufPtr+2SizeOk	ldy Src1	; get offset to next value from OutScan	lda [Scratch],y	; get the next H coord	cmp #MaxInt	; is it MaxInt?	bne OutLoop	; no, go for more	jmp NxtVert	; loop for next vertMemError	pha	; save error	jsl GetRidOfS	pla	; get error back	sec	; ensure error flag	is set	rtlDone	ldy #2	; offset to ListPtr	index	lda ListPtr	; get size	sta [BufPtr],y	; save size	lsr A	; divide by 2	lsr A	; divided by 4	dea	; minus 1 to generate # of points	sta PtCount	; update itGetRidOfS	pei ScratchHandle+2	pei ScratchHandle	_DisposeHandle	; get rid of it	rtl	; get out of here****************************************************************** Procedure ExpandA** Change History** 7 July 87    SEG	   (System Disk 2.1)** This proc is patched to be able to get to InsetScan* below.  This code	is only run when the operation to perform* is inset.  Other operations go through ROM.*****************************************************************ExpandA	lda #10	; size of rectangular region	cmp [RgnPtrA]	; set flags on 10-length	bne NotRectA	; if not Rect, deal	with that	Movelong Scratch,PtrBaseA ; pointer to first fake region	ldy #2	lda [RgnPtrA],y	; BBox.Top	sta [PtrBaseA]	; V 1	ldy #4	lda [RgnPtrA],y	; BBox.Left	ldy #2	sta [PtrBaseA],y	; H 1.1	ldy #10	sta [PtrBaseA],y	; H 2.1	ldy #6	lda [RgnPtrA],y	; BBox.Bottom	ldy #8	sta [PtrBaseA],y	; V 2	lda [RgnPtrA],y	; BBox.RIght	ldy #4	sta [PtrBaseA],y	; H 1.2	ldy #12	sta [PtrBaseA],y	; H 2.2	lda #MaxInt	ldy #6	sta [PtrBaseA],y	; store MaxInt	ldy #14	sta [PtrBaseA],y	; store MaxInt	ldy #16	sta [PtrBaseA],y	; store MaxInt	stz PtrA	; zero PtrA	rts	; get outa hereNotRectA	Movelong RgnPtrA,PtrBaseA ; use the actual pointer	lda #10	; get offset to data	sta PtrA	; save it	rts	; get outa here****************************************************************** Procedure ExpandB** Change History** 7 July 87    SEG	   (System Disk 2.1)** This proc is patched to be able to get to InsetScan* below.  This code	is only run when the operation to perform* is inset.  Other operations go through ROM.*****************************************************************ExpandBFakeOff	equ 18	; offset in Scratch	to FakeB	lda #10	; size of rectangular region	cmp [RgnPtrB]	; set flags on 10-length	bne NotRectB	; if not Rect, deal	with that	Movelong Scratch,PtrBaseB ; point us at	Scratch region	ldy #2	; offset to BBox	lda [RgnPtrB],y	; BBox.Top	ldy #FakeOff	sta [PtrBaseB],y	; V 1	ldy #4	lda [RgnPtrB],y	; BBox.Left	ldy #2+FakeOff	sta [PtrBaseB],y	; H 1.1	ldy #10+FakeOff	sta [PtrBaseB],y	; H 2.1	ldy #6	lda [RgnPtrB],y	; BBox.Bottom	ldy #8+FakeOff	sta [PtrBaseB],y	; V 2	ldy #8	lda [RgnPtrB],y	; BBox.RIght	ldy #4+FakeOff	sta [PtrBaseB],y	; H 1.2	ldy #12+FakeOff	sta [PtrBaseB],y	; H 2.2	lda #MaxInt	ldy #6+FakeOff	sta [PtrBaseB],y	; store MaxInt	ldy #14+FakeOff	sta [PtrBaseB],y	; store MaxInt	ldy #16+FakeOff	sta [PtrBaseB],y	; store MaxInt	lda #FakeOff	; get fake offset	sta PtrB	; offset to B	rts	; get outa hereNotRectB	Movelong RgnPtrB,PtrBaseB ; use the real region	lda #10	; get offset to data	sta PtrB	; save it	rts	; get out here****************************************************************** Procedure InsetScan**   Accepts offsets	into Scratch buffer	in Src1 and*   Dst.  It then horizontally insets an inversion scan by DH.*   The input scan is a sorted array of	integers terminated	by*   MaxInt.  The output scan contains the inversion coordinates*   for the inset.** Change History** 7 July 87    SEG	   (System Disk 2.1)** When outsetting a	region, the region was getting disfigured* when inversion points needed to cancel out.  The problem* was a misplaced label below.  All the	rest of the* code in this file	is here because it was necessary to* perform the patch.** 25 Jan 88    GCP	   (System Disk 3.2)** We weren't checking for matching points when we did* InsetScan.  We are now.*****************************************************************InsetScan	lda DH	; is dh negative?	bmi Outset	; yes, outsetInset	ldy Src1	; get first offset	lda [SrcBase1],y	; get first value	sta Temp	; save it	cmp #MaxInt	; check for terminator	beq DoneOutset	; quit when found	IncYWd	; bump y	lda [SrcBase1],y	; get second value	IncYWd	; bump y again	sty Src1	; save it	sec	; prepare for subtract	sbc DH	; subtract from right	sta Temp+2	; save it also	lda Temp	; get first back	clc	; prepare for add	adc DH	; add to left	sta Temp	; save it	cmp Temp+2	; set flags on left-right	bpl Inset	; if left >= right,	skip both	ldy Dst	; get destination offset	sta [Scratch],y	; save first	IncYWd	; bump y	lda Temp+2	; get first back	sta [Scratch],y	; save second	IncYWd	; bump y	sty Dst	; save pointer	bra Inset	; loop entire scanDoneOut	sty Src1	; update itDoneOutset	ldy Dst	; get destination pointer	lda #MaxInt	; get end of scan	sta [Scratch],y	; mark it	IncYWd	; bump y	sty Dst	; there!	rts	; All done!* each pair of coords, outset them and cancel if they crossOutset	lda #-MaxInt	; set oldrightOutsetLoop	sta OldRight	; to -Maxint	ldy Src1	; get next offset	lda [SrcBase1],y	; load next left value	IncYWd	; bump it	sta Temp	; save it	cmp #MaxInt	; check for terminator	beq DoneOut	; if it is, we're done	lda [SrcBase1],y	; get right value	IncYWd	; bump y	sty Src1	; save it	ldy Dst	; get ready for store	sec	; prepare for subtract	sbc DH	; right-DH	sta Temp+2	; save it	lda Temp	; get left back	clc	; prepare for add	adc DH	; add to left	cmp OldRight	; is left <= OldRight	beq DisposePoints	; added 25 Jan 88 GCP	bpl OutOk	; no, continueDisposePoints	DecYWd	; decrement Dst by 2	bra OutOk2	; and continueOutOk	sta [Scratch],y	; save left point	IncYWd	; bump y;; this is the line that changed.  Label	OutOK2 moved from; next line to this	one.;OutOK2	lda Temp+2	; get right back	sta [Scratch],y	; save right point	IncYWd	; bump y	sty Dst	; save it	bra OutsetLoop	; loop for entire scan****************************************************************** Procedure XorScan**   Accepts offsets	into Scratch buffer	in Src1, Src2, and*   Dst.  It then forms the exclusive or of two inversion scans.*   Each input scan	is a sorted array of integers terminated by*   MaxInt.  The output scan contains all input coordinates	from*   each, but with duplicate pairs cancelled.  It also is*   terminated by MaxInt.** Change History** 7 July 87    SEG	   (System Disk 2.1)** This proc is patched to be able to get to InsetScan* below.  This code	is only run when the operation to perform* is inset.  Other operations go through ROM.*****************************************************************XorScan	ldy Src1	; get offset to A	lda [SrcBase1],y	; get Next A	sta Next1	; save it	IncYWd	; bump y	sty Src1	; save pointer	ldy Src2	; get next B offset	lda [Scratch],y	; get next B	sta Next2	; save it	IncYWd	; bump y	sty Src2	; save itNext	ldy Dst	; set up the y register	lda Next2	; get second	cmp Next1	; set flags on Next2-Next1	beq Equal	; the same, so cancel	bpl Less1	; if Next1 < Next2,	take from 1Less2	sta [Scratch],y	; save the second value	IncYWd	; bump Dst	sty Dst	; and save it	ldy Src2	; get offset to second	lda [Scratch],y	; get next value	sta Next2	; save it	IncYWd	; bump y	sty Src2	; save it	Bra Next	; jump right in thereLess1	lda Next1	; get first back	sta [Scratch],y	; put it	IncYWd	; bump Dst	sty Dst	; and save it	ldy Src1	; get offset to first	lda [SrcBase1],y	; get next value	sta Next1	; save it	IncYWd	; bump y	sty Src1	; save it	bra Next	; jump back in thereEqual	cmp #MaxInt	; all done?	bne XorScan	; if so, we're cool	sta [Scratch],y	; save terminator, y already = Dst	IncYWd	; probably not necessary	sty Dst	; nor this either	rts	; go home; go home****************************************************************** ResizeHandle*****************************************************************LocalResizeHandle		;* enter with pointer to handle on zero page in x* Sample usage**     lda NewHandleSize*     ldx #RgnHandleA*     jsr ResizeHandle*     sta RgnPtrA*     stx RgnPtrA+2	pha	; push size (02)	pea 0	; push 0 for high word of size (04)	pha	; push low word of size (06)	jsr LocalUnlockHandle ; pass X as pointer* UnlockHandle leaves a copy of the handle in Temp for us.	Long word size* is still on the stack	pei Temp+2	; push handle high (08)	pei Temp	; push handle low (0A)	_SetHandleSize	; handle size is at	top of stack (02)	bcs Error	; we found an error, A & X are invalidNewEntry		;	jsr LocalQuickDeref	; handle still in Temp, redereference it	sta Temp	; pointer is in A &	X	stx Temp+2	pla	; get size back (00)	sta [Temp]	; set size for regions, invpt buffers	lda Temp	; pointer is in A &	X	rtsError	ply	; error in A, carry	is still set (00)	ldx #$FFFF	; invalidate pointer	rts****************************************************************** GetNewHandle** This routine is not itdentical to what is in the ROM.* It is different in that it does not branch to NEWEntry (a* part of resize handle) since that is not in the patch.** Instead, it has the part of NewENTRY that matters in line* here.*****************************************************************LocalGetNewHandle		;* It accepts a size	in A and an offset to the zero page handle variable* in X.  Upon return it has initialized	a new handle, dereferenced it,* and set the first	two bytes of the handle data to the length of the* handle, which is what regions and buffers want.  Because it sets the* length it assumes	the size (in A) will never be less than	2 bytes.* It puts a copy of	the new handle into	the location pointed at by X.* The dereferenced pointer is returned in A and X.	pha	; save size	phx	; save offset	pea 0	; make room for result	pea 0	pea 0	; high word of count	pha	; push the requested size	pei UserID	pea MyRgnAttributes	pea 0	; push location requirements	pea 0	_NewHandle	; allocate a new one	ply	sty Temp	ply	sty Temp+2	bcs HandleError	; if an error, clean up	plx	; get offset back	sty 2,x	; save high word to	real handle	ldy Temp	; get low word back	sty 0,x	; save low word to real handle* The size is still	on the stack.  This	now looks like we've just resized* a handle, so branch upwards and use the code we've already written.** This is where it branched to NewENTry	jsr LocalQuickDeref	; handle still in Temp, redereference it	sta Temp	; pointer is in A &	X	stx Temp+2	pla	; get size back (00)	sta [Temp]	; set size for regions, invpt buffers	lda Temp	; pointer is in A &	X	rtsHandleError	ply	; discard offset	ply	; discard size	rts****************************************************************** DerefHandle*****************************************************************LocalDerefHandle		;* enter with zero page offset to src in	X* sample usage:**     ldx #RgnHandleA*     jsr DerefHandle*     sta RgnPtrA*     stx RgnPtrA+2	lda 0,x	sta Temp	lda 2,x	sta Temp+2LocalQuickDeref		; ; enter here if Temp has handle already* sample usage:*     jsr QuickDeref	; Temp still has handle*     sta RgnPtrA*     stx RgnPtrA+2* handle is in Temp; lock it down	ldy #4	lda [Temp],y	ora #$8000	sta [Temp],y* dereference it, leaving low word in A	and high word in X	ldy #2	lda [Temp],y	tax	lda [Temp]	rts****************************************************************** Procedure UnlockHandle*****************************************************************LocalUnlockHandle		;* enter with zero page offset to handle	in x* Sample usage**     ldx #RgnHandleA*     jsr UnlockHandle	lda 0,x	sta Temp	lda 2,x	sta Temp+2* unlock it	ldy #4	lda [Temp],y	and #$7FFF	sta [Temp],y* leave with Temp still holding the handle so related routines* can use it	rts	ENDP;                copy rdf.patch2/maprgn****************************************************************** MapRgn2** 07 Jul 87    SEG** Maprgn and PutRgn	did not agree on the location of where* the input to putrgn should be.  This was because of a change* made to the region drawing routines after put rgn was* written.  This change puts a copy of the handle in* RgnHandleA and RgnHandleC instead of just RgnHandleA.* This should make PutRgn happy.*****************************************************************	EXPORT MapRgn2MapRgn2	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3ToRectPtr	equ RTL2+3FromRectPtr	equ ToRectPtr+4Rgn	equ FromRectPtr+4IntoROM	equ $FE6248	jsr QDStart2	lda Rgn,s	sta RgnHandleC	lda Rgn+2,s	sta RgnHandleC+2	jml IntoROM	ENDP	END